const fmt = (n:number) => new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(Number(n)||0);
const num = (n:number) => new Intl.NumberFormat('en-IN').format(Number(n)||0);
