      return {title:(isParty?'Party-wise':isAccount?'Account-wise':'Category-wise')+' Ledger — Summary',note:isParty?'Party closing balances are provisional where opening balances, demand mapping or receipt allocation are incomplete.':isAccount?'Opening balances use the earliest available reconciliation record and must be checked against the approved opening balance.':'Income/expense category movement is not a brought-forward accounting balance.',headers:isParty?['Party Name','Opening Balance','Demand / Charges','Receipts','Closing Receivable']:isAccount?['Account','Opening Balance','Receipts','Payments','Closing Balance']:['Category Group','Category','Receipts / Income','Payments / Expense','Net Movement'],rows};
